import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    if n == 1:
        if a[0] == 0:
            print("YES")
            print("0")
        else:
            print("NO")
        return

    if 0 not in a:
        print("NO")
        return

    # Find the first occurrence of 0
    first_zero_index = a.index(0)

    # If the first zero is at the end, we can't make the expression false
    if first_zero_index == n - 1:
        print("NO")
        return

    # Construct the expression
    expression = ""
    for i in range(n):
        if i == first_zero_index:
            expression += "("
        expression += str(a[i])
        if i == first_zero_index + 1:
            expression += "->"
        elif i > first_zero_index + 1:
            expression += "->"
        if i == n - 1:
            expression += ")"

    print("YES")
    print(expression)

if __name__ == "__main__":
    main()
